@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#f3f0e8;--muted:#989bad;--dim:#626679;--bg:#101422;--panel:#171c2d;--panel2:#1d2336;--line:#2b3247;--lime:#c8f169;--coral:#ff987e;--cyan:#83d9dc;--violet:#b8a2ff;--serif:Georgia,'Times New Roman',serif;--sans:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif;--mono:'DM Mono',monospace}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px var(--sans);min-height:100vh;background-image:radial-gradient(ellipse at 48% -15%,#27304a 0,transparent 46%),radial-gradient(circle at 8% 60%,#171c30 0,transparent 28%)}button{font:inherit;color:inherit}button:focus-visible,a:focus-visible{outline:2px solid var(--lime);outline-offset:3px}.app-shell{max-width:1440px;margin:auto;padding:0 6.1vw;min-height:100vh;display:flex;flex-direction:column}.topbar{height:86px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff13}.wordmark{display:flex;gap:12px;align-items:center;text-decoration:none;color:var(--ink);font:700 16px var(--display);letter-spacing:.11em}.wordmark small{display:block;color:var(--muted);font:10px var(--mono);letter-spacing:.13em;margin-top:3px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid #c8f16988;border-radius:50%;font-size:23px;color:var(--lime)}.top-meta{display:flex;gap:10px;align-items:center;font:10px var(--mono);letter-spacing:.1em;color:var(--muted)}.live-dot{height:7px;width:7px;background:var(--lime);border-radius:50%;box-shadow:0 0 10px #c8f16988}.meta-divider{height:17px;border-left:1px solid var(--line);margin:0 6px}.icon-button{border:0;background:transparent;color:var(--muted);padding:8px;cursor:pointer}.main-content{flex:1;padding:30px 0 36px}.site-footer{height:53px;border-top:1px solid #ffffff13;display:flex;align-items:center;justify-content:space-between;font:9px var(--mono);letter-spacing:.15em;color:var(--dim)}.site-footer b{color:var(--lime);font-weight:400}.eyebrow{font:10px var(--mono);letter-spacing:.17em;text-transform:uppercase;color:var(--lime)}h1,h2,h3,p{margin-top:0}h1,h2,h3{font-family:var(--display)}.button{border:0;cursor:pointer;padding:13px 19px;background:var(--lime);color:#171a1f;font-weight:700;font-size:12px;letter-spacing:.07em;text-transform:uppercase;transition:transform .18s,filter .18s}.button:hover{transform:translateY(-2px);filter:brightness(1.08)}.button:disabled{opacity:.4;cursor:not-allowed;transform:none}.button.secondary{color:var(--ink);background:#ffffff0b;border:1px solid var(--line)}.button.small{font-size:10px;padding:10px 13px}.text-button{background:none;border:0;color:var(--muted);font:11px var(--mono);cursor:pointer}.text-button:hover{color:var(--lime)}.panel{background:linear-gradient(145deg,#1a2032,#151a29);border:1px solid #ffffff12}.pill{display:inline-flex;align-items:center;border:1px solid var(--line);padding:5px 8px;color:var(--muted);font:9px var(--mono);letter-spacing:.08em;text-transform:uppercase}.accent{color:var(--lime)}
/* opening */
.intro{min-height:calc(100vh - 170px);display:grid;grid-template-columns:1.04fr .96fr;align-items:center;gap:5vw;padding:15px 0 38px}.intro-copy{max-width:560px}.intro-copy .eyebrow{display:flex;gap:10px;align-items:center}.intro-copy .eyebrow:before{content:'';width:28px;border-top:1px solid var(--lime)}.intro h1{font-size:clamp(54px,7vw,98px);line-height:.91;letter-spacing:-.08em;margin:22px 0 21px;font-weight:500}.intro h1 em{font-family:var(--serif);font-weight:400;color:var(--lime);letter-spacing:-.06em}.lede{color:#b0b3c1;line-height:1.75;max-width:435px;font-size:15px}.intro-actions{display:flex;align-items:center;gap:20px;margin-top:28px}.hero-note{font:10px var(--mono);color:var(--dim);line-height:1.6}.hero-art{position:relative;min-height:540px;display:grid;place-items:center}.planet-scene{position:relative;width:min(43vw,500px);aspect-ratio:1;border-radius:50%;overflow:hidden;background:radial-gradient(circle at 38% 30%,#536b68 0 5%,#2c5355 23%,#293657 49%,#171f39 68%,#101422 69%);box-shadow:inset -28px -17px 58px #060912cc,0 30px 100px #07101daa}.planet-scene:before{content:'';position:absolute;inset:10%;border-radius:50%;background:repeating-linear-gradient(169deg,transparent 0 42px,#d2bf8555 44px 48px,transparent 50px 85px);opacity:.48;transform:rotate(-19deg);mask-image:radial-gradient(ellipse,#000 15%,transparent 73%)}.planet-scene:after{content:'';position:absolute;inset:0;border-radius:50%;box-shadow:inset -31px -10px 55px 8px #0b1021,inset 0 0 0 1px #e2ffc222}.orbit{position:absolute;width:118%;height:35%;border:1px solid #d5d9bb66;border-radius:50%;transform:rotate(-24deg);z-index:2}.orbit:after{content:'✦';position:absolute;right:9%;top:12%;color:var(--lime);font-size:14px}.moon{position:absolute;width:42px;height:42px;right:14%;top:20%;border-radius:50%;background:radial-gradient(circle at 35% 30%,#eedcb4,#9c907a 75%);box-shadow:0 0 28px #d1c18b55}.flora{position:absolute;z-index:1;bottom:15%;left:28%;height:35%;width:34%;filter:drop-shadow(0 0 12px #a5e8b733)}.flora:before,.flora:after{content:'';position:absolute;bottom:0;left:48%;width:3px;height:100%;background:#a4bc8e;transform:rotate(8deg);border-radius:50%}.flora:after{height:77%;transform:rotate(-27deg);left:20%;bottom:-1%}.leaf{position:absolute;z-index:2;width:38px;height:18px;border-radius:100% 0 100% 0;background:linear-gradient(135deg,#d9e89b,#759f83);transform:rotate(-32deg);left:16%;bottom:49%}.leaf.l2{left:49%;bottom:68%;transform:rotate(65deg);background:linear-gradient(135deg,#b9db9d,#598d81)}.leaf.l3{left:7%;bottom:25%;transform:rotate(19deg);width:45px}.leaf.l4{left:51%;bottom:38%;transform:rotate(174deg);background:linear-gradient(135deg,#d9e89b,#759f83)}.starlight{position:absolute;color:#e5efcc;font-size:12px;z-index:2}.starlight.s1{top:26%;left:25%}.starlight.s2{top:48%;right:19%;font-size:8px}.starlight.s3{bottom:25%;right:27%;font-size:7px}.scene-caption{position:absolute;bottom:1%;right:0;font:9px var(--mono);letter-spacing:.13em;color:var(--dim)}.scene-caption span{color:var(--lime)}.intro-mini{display:flex;gap:23px;margin-top:45px;border-top:1px solid #ffffff18;padding-top:16px}.intro-mini div{font:9px var(--mono);color:var(--dim);letter-spacing:.08em}.intro-mini b{display:block;color:var(--ink);font:500 13px var(--display);margin-bottom:4px}
/* character creation */
.creation{max-width:1050px;margin:auto}.creation-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:26px}.creation h1{font-size:40px;letter-spacing:-.05em;margin:8px 0}.creation-intro{max-width:480px;color:var(--muted);font-size:13px;line-height:1.65;margin:0}.step-label{font:10px var(--mono);color:var(--dim)}.step-label b{color:var(--lime)}.name-row{display:flex;align-items:center;gap:14px;padding:18px 20px;margin-bottom:18px}.name-row label{font:9px var(--mono);letter-spacing:.13em;color:var(--muted);white-space:nowrap}.name-row input{border:0;border-bottom:1px solid #596078;background:none;color:var(--ink);outline:0;padding:7px 3px;font:18px var(--display);width:200px}.name-row input:focus{border-color:var(--lime)}.creation-grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}.choice-section{padding:21px}.choice-section h2{font-size:17px;margin:6px 0 5px}.choice-section>p{font-size:11px;line-height:1.5;color:var(--muted);margin-bottom:14px}.choice-list{display:grid;gap:8px}.choice-card{display:flex;text-align:left;align-items:center;gap:12px;padding:11px 12px;border:1px solid #ffffff13;background:#ffffff04;cursor:pointer;min-height:65px;transition:.18s}.choice-card:hover,.choice-card.selected{border-color:#c8f16999;background:#c8f1690c}.choice-icon{display:grid;place-items:center;width:36px;height:36px;background:#ffffff08;font-size:19px;flex-shrink:0;color:var(--choice,var(--lime))}.choice-copy{flex:1}.choice-copy b{font:600 13px var(--display);display:block}.choice-copy small{color:var(--muted);font-size:10px}.choice-card .check{opacity:0;color:var(--lime);font-size:13px}.choice-card.selected .check{opacity:1}.creation-bottom{display:flex;align-items:center;justify-content:space-between;margin-top:18px}.destiny-preview{color:var(--muted);font-size:11px}.destiny-preview strong{color:var(--ink);font-family:var(--display)}
/* game dashboard */
.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 275px;gap:24px;max-width:1200px;margin:auto}.game-main{min-width:0}.welcome-row{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:19px}.welcome-row h1{font-size:35px;letter-spacing:-.055em;margin:6px 0 4px}.welcome-row p{font-size:11px;color:var(--muted);margin:0}.day-badge{border:1px solid var(--line);padding:10px 14px;text-align:right;font:9px var(--mono);color:var(--muted);letter-spacing:.08em}.day-badge strong{display:block;color:var(--lime);font:500 18px var(--display);margin-top:4px}.scene-card{position:relative;min-height:280px;overflow:hidden;padding:25px 27px;background:#192335;border:1px solid #ffffff14}.scene-card:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,#121a2aeF 0%,#141c2ad9 43%,#141c2a22 100%),linear-gradient(0deg,#151b2de8,transparent 56%),var(--scene-art,radial-gradient(ellipse at 77% 31%,#8d8a5b 0 3%,transparent 4%),radial-gradient(ellipse at 81% 28%,#4d695f 0 13%,transparent 14%),linear-gradient(160deg,#2c4a4b,#1d3040 50%,#222438)) center/cover}.scene-content{position:relative;z-index:1;max-width:430px}.scene-location{font:9px var(--mono);letter-spacing:.15em;color:var(--lime);text-transform:uppercase}.scene-card h2{font-size:31px;letter-spacing:-.05em;margin:12px 0 8px}.scene-card p{color:#c3c4ca;font-size:12px;line-height:1.7;max-width:390px}.scene-footer{display:flex;align-items:center;gap:14px;margin-top:19px}.scene-coords{font:9px var(--mono);letter-spacing:.08em;color:#a6aaba}.scene-card .scene-flower{position:absolute;right:10%;bottom:-14%;font-size:170px;color:#c5f07088;filter:drop-shadow(0 0 25px #c5f07055);transform:rotate(-16deg);line-height:1;z-index:0}.action-grid{display:grid;grid-template-columns:1.05fr 1fr 1fr;gap:10px;margin:13px 0 22px}.action-card{background:#191f31;border:1px solid #ffffff13;padding:15px 15px 14px;text-align:left;cursor:pointer;min-height:110px;transition:.18s;position:relative}.action-card:hover{border-color:#c8f16988;transform:translateY(-2px)}.action-card .action-icon{font-size:20px;color:var(--lime);display:block;margin-bottom:11px}.action-card strong{font:600 13px var(--display);display:block;margin-bottom:4px}.action-card small{color:var(--muted);font-size:10px}.section-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.section-title h3{margin:0;font-size:14px}.section-title span{font:9px var(--mono);color:var(--dim);letter-spacing:.1em}.journal-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}.journal-entry{border:1px solid #ffffff10;background:#ffffff04;padding:12px;display:flex;gap:10px;align-items:flex-start}.journal-entry .journal-icon{color:var(--lime);font-size:14px}.journal-entry b{font:500 11px var(--display);display:block;margin-bottom:3px}.journal-entry small{color:var(--muted);font:9px var(--mono);line-height:1.5}.sidebar{display:flex;flex-direction:column;gap:12px}.side-panel{padding:17px}.profile-head{display:flex;gap:12px;align-items:center;margin-bottom:15px}.avatar{width:44px;height:44px;display:grid;place-items:center;background:radial-gradient(circle at 40% 30%,#91ab91,#354a5a 65%);border:1px solid #d0e7bb55;border-radius:50%;font-size:22px}.profile-head h3{font-size:14px;margin:0 0 3px}.profile-head small{font:9px var(--mono);color:var(--lime);letter-spacing:.08em}.xp-row{display:flex;justify-content:space-between;color:var(--muted);font:9px var(--mono);margin-bottom:6px}.xp-bar,.meter{height:4px;background:#ffffff12;overflow:hidden}.xp-bar i,.meter i{height:100%;display:block;background:var(--lime);transition:width .4s}.stats-line{display:grid;grid-template-columns:repeat(3,1fr);margin-top:14px;text-align:center}.stats-line div+div{border-left:1px solid var(--line)}.stats-line b{display:block;font:600 15px var(--display)}.stats-line small{font:8px var(--mono);color:var(--dim);letter-spacing:.08em}.inventory-panel h3{font-size:13px;margin:0 0 13px}.resource-row{display:flex;align-items:center;justify-content:space-between;margin:9px 0;font:10px var(--mono);color:var(--muted)}.resource-row span:first-child{display:flex;align-items:center;gap:8px}.resource-row b{color:var(--ink);font-weight:400}.resource-gem{width:7px;height:7px;background:var(--res-color,var(--lime));border-radius:2px;transform:rotate(45deg)}.gear-row{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin:9px 0}.gear-row b{font:10px var(--mono);color:var(--ink)}.sidebar-actions{display:grid;grid-template-columns:1fr 1fr;gap:7px}.sidebar-actions button{background:#ffffff06;border:1px solid var(--line);font:9px var(--mono);letter-spacing:.07em;padding:10px 4px;cursor:pointer}.sidebar-actions button:hover{border-color:var(--lime);color:var(--lime)}
/* modal / realm */
.modal-backdrop{position:fixed;inset:0;background:#080b13cf;z-index:10;display:grid;place-items:center;padding:18px;backdrop-filter:blur(8px)}.modal{width:min(720px,100%);max-height:min(90vh,850px);overflow:auto;background:#171c2d;border:1px solid #ffffff21;box-shadow:0 25px 100px #0009;padding:26px;animation:modal-in .2s ease-out}@keyframes modal-in{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}.modal-head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:15px;margin-bottom:19px}.modal-head h2{font-size:26px;letter-spacing:-.04em;margin:5px 0}.close-button{background:none;border:1px solid var(--line);color:var(--muted);width:34px;height:34px;cursor:pointer}.realm-list{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.realm-card{position:relative;min-height:142px;padding:16px;border:1px solid #ffffff18;cursor:pointer;background:linear-gradient(145deg,#253441,#1b2030);overflow:hidden}.realm-card:after{content:attr(data-glyph);position:absolute;right:8px;bottom:-29px;font-size:108px;opacity:.13;color:var(--realm-color,var(--lime));font-family:var(--serif)}.realm-card:hover{border-color:var(--realm-color,var(--lime))}.realm-card h3{position:relative;z-index:1;font-size:16px;margin:8px 0}.realm-card p{position:relative;z-index:1;color:#afb4c0;font-size:10px;line-height:1.55;max-width:265px;margin:0}.realm-card .realm-difficulty{font:8px var(--mono);color:var(--realm-color,var(--lime));letter-spacing:.1em}.realm-card.locked{opacity:.55;cursor:not-allowed}.explore-layout{display:grid;grid-template-columns:1.15fr .85fr;gap:15px}.explore-art{min-height:220px;position:relative;display:flex;align-items:flex-end;padding:18px;background:linear-gradient(0deg,#101422dd,transparent 70%),var(--scene-art,linear-gradient(140deg,#31575a,#282944)) center/cover;border:1px solid #ffffff17}.explore-art .explore-caption{font:9px var(--mono);color:var(--lime);letter-spacing:.12em}.explore-text{color:#c3c5cd;font-size:12px;line-height:1.8}.explore-options{display:grid;gap:8px;margin-top:16px}.explore-options button{background:#ffffff06;text-align:left;border:1px solid var(--line);padding:12px;cursor:pointer}.explore-options button:hover{border-color:var(--lime)}.explore-options strong{display:block;font:500 12px var(--display);margin-bottom:3px}.explore-options small{color:var(--muted);font-size:10px}.result-card{border:1px solid #ffffff18;padding:21px;margin:10px 0 15px;background:#ffffff04}.result-card .result-icon{font-size:28px;color:var(--lime)}.result-card h3{font-size:20px;margin:10px 0}.result-card p{color:#b7bac5;font-size:12px;line-height:1.7}.loot-row{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.loot-chip{font:9px var(--mono);padding:6px 8px;background:#c8f16912;border:1px solid #c8f16942;color:var(--lime)}
/* alchemy */
.recipe-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.recipe{border:1px solid #ffffff17;padding:13px;background:#ffffff04}.recipe h3{font-size:13px;margin:0 0 6px}.recipe p{color:var(--muted);font-size:10px;margin:0 0 10px}.recipe-footer{display:flex;justify-content:space-between;align-items:center;font:9px var(--mono);color:var(--dim)}.recipe-footer b{color:var(--lime);font-weight:400}.recipe-footer button{font:9px var(--mono);padding:7px 9px;border:1px solid #c8f16955;background:#c8f1690d;color:var(--lime);cursor:pointer}.recipe-footer button:disabled{opacity:.35;cursor:not-allowed}.recipe-inventory{font:10px var(--mono);color:var(--muted);display:flex;gap:12px;flex-wrap:wrap;margin:15px 0 5px}.recipe-inventory b{color:var(--ink);font-weight:400}.equip-list{display:grid;gap:9px}.equip-item{display:flex;justify-content:space-between;align-items:center;border:1px solid #ffffff16;padding:12px}.equip-item b{font:500 12px var(--display)}.equip-item small{display:block;color:var(--muted);font:9px var(--mono);margin-top:4px}.equip-item button{font:9px var(--mono);background:#ffffff08;border:1px solid var(--line);padding:8px 10px;cursor:pointer}.equip-item button:disabled{color:var(--lime);cursor:default;border-color:#c8f16945}.story-panel{padding:19px;border-left:2px solid var(--lime);background:#ffffff05;color:#c4c6cf;font:13px/1.9 var(--serif)}.story-panel b{color:var(--lime);font-weight:400}.toast{position:fixed;z-index:30;bottom:22px;left:50%;transform:translate(-50%,20px);padding:12px 16px;background:#e1f1b3;color:#151a20;font:11px var(--mono);opacity:0;transition:.25s;pointer-events:none;box-shadow:0 8px 28px #0005}.toast.show{opacity:1;transform:translate(-50%,0)}.empty{text-align:center;padding:28px;color:var(--muted);font-size:12px}
@media(max-width:900px){.app-shell{padding:0 4vw}.intro{gap:2vw}.hero-art{min-height:440px}.game-layout{grid-template-columns:minmax(0,1fr) 245px;gap:14px}.scene-card{min-height:250px}.action-grid{gap:7px}.action-card{padding:12px}.side-panel{padding:14px}}
@media(max-width:680px){.app-shell{padding:0 17px}.topbar{height:65px}.top-meta{font-size:8px}.wordmark{font-size:13px}.brand-mark{width:30px;height:30px}.main-content{padding:20px 0 27px}.site-footer{font-size:8px}.intro{min-height:initial;grid-template-columns:1fr;gap:0;padding:18px 0 25px}.intro-copy{order:1}.intro h1{font-size:62px;margin:18px 0}.lede{font-size:13px}.hero-art{min-height:325px;grid-row:1;margin-bottom:12px}.planet-scene{width:min(75vw,330px)}.scene-caption{right:4%}.intro-mini{margin-top:28px}.creation-head{display:block}.creation h1{font-size:34px}.creation-intro{font-size:12px;margin:10px 0}.step-label{display:block;margin-top:12px}.creation-grid{grid-template-columns:1fr}.choice-section{padding:17px}.name-row{padding:14px;gap:8px}.name-row input{width:min(52vw,210px);font-size:16px}.creation-bottom{gap:12px}.destiny-preview{font-size:10px}.game-layout{grid-template-columns:1fr;gap:15px}.welcome-row{margin-bottom:13px}.welcome-row h1{font-size:29px}.scene-card{min-height:260px;padding:19px}.scene-card h2{font-size:27px}.scene-card .scene-flower{font-size:130px;right:0}.action-grid{grid-template-columns:1fr 1fr}.action-card{min-height:104px}.action-card:first-child{grid-column:span 2;min-height:88px}.action-card:first-child .action-icon{float:left;margin:1px 12px 20px 0}.journal-list{grid-template-columns:1fr}.sidebar{display:grid;grid-template-columns:1fr 1fr}.profile-panel{grid-column:span 2}.inventory-panel{grid-column:span 2}.modal{padding:19px}.modal-head h2{font-size:22px}.realm-list{grid-template-columns:1fr}.realm-card{min-height:125px}.explore-layout{grid-template-columns:1fr}.explore-art{min-height:155px}.recipe-grid{grid-template-columns:1fr}.creation-bottom .button{padding:12px}.intro-mini div{font-size:8px}.intro-mini b{font-size:12px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;animation-duration:.01ms!important;transition-duration:.01ms!important}}

const $ = (sel, root=document) => root.querySelector(sel);
const app = $('#main');
const SAVE_KEY = 'starroot-save-v1';
const classes = [
  {name:'Wayfarer',icon:'⌁',color:'#c8f169',tag:'the road is your teacher',desc:'A pathfinder who turns uncertainty into momentum.',fate:'The one who finds a way through.',stats:{grit:2,insight:1,grace:1}},
  {name:'Mender',icon:'✿',color:'#ff987e',tag:'nothing living is beyond repair',desc:'A tender-hearted fixer who makes broken things whole.',fate:'The one who keeps the world together.',stats:{grit:1,insight:2,grace:1}},
  {name:'Seer',icon:'☼',color:'#b8a2ff',tag:'look twice; see what could be',desc:'A patient observer who reads the shape of possibility.',fate:'The one who sees the turning point.',stats:{grit:1,insight:1,grace:2}},
  {name:'Ravager',icon:'⚒',color:'#ff987e',tag:'make room for what comes next',desc:'A bold breaker of barriers, never cruel without cause.',fate:'The one who makes a new beginning.',stats:{grit:3,insight:0,grace:1}},
  {name:'Artisan',icon:'◇',color:'#83d9dc',tag:'imagine it; then make it real',desc:'A practical dreamer who gives ideas a useful shape.',fate:'The one who builds what is missing.',stats:{grit:1,insight:2,grace:1}},
  {name:'Pilgrim',icon:'☾',color:'#83d9dc',tag:'everywhere is somewhere to belong',desc:'A generous connector who makes strangers into kin.',fate:'The one who brings distant hearts together.',stats:{grit:1,insight:1,grace:2}}
];
const aspects = [
  {name:'Ember',icon:'✦',color:'#ff987e',tag:'the spark that changes everything',desc:'You kindle courage, warmth, and necessary change.',power:'Flame',bonus:'Deals extra damage to tangled things.'},
  {name:'Tide',icon:'≈',color:'#83d9dc',tag:'the patient strength of water',desc:'You bend, remember, and find the way through.',power:'Flow',bonus:'Finds extra resources along the way.'},
  {name:'Grove',icon:'❋',color:'#c8f169',tag:'the stubborn joy of growing',desc:'You shelter what is small until it is strong.',power:'Bloom',bonus:'Restores a little health after each outing.'},
  {name:'Gale',icon:'⌁',color:'#b8a2ff',tag:'the freedom to become',desc:'You carry messages, possibility, and change.',power:'Wind',bonus:'Escapes danger and earns extra experience.'},
  {name:'Stone',icon:'⬡',color:'#e4c995',tag:'the quiet promise of endurance',desc:'You hold fast, stand firm, and make safe ground.',power:'Root',bonus:'Shrugs off damage from hazards.'},
  {name:'Hush',icon:'☾',color:'#b8a2ff',tag:'the meaning inside the silence',desc:'You tend to secrets and the soft spaces between.',power:'Dream',bonus:'Reveals unusual finds in hidden places.'}
];
const realms = [
  {name:'Mosslight Basin',biome:'VERDANT LOWLAND',desc:'A valley of soft green glow, where an ancient river braids through the roots of a sleeping giant.',glyph:'❋',color:'#b9e983',art:'radial-gradient(ellipse at 75% 30%,#d1d58f 0 2%,transparent 3%),radial-gradient(ellipse at 77% 35%,#7ab99a 0 18%,transparent 19%),linear-gradient(158deg,#375b57,#263a4d 62%,#24263c)',loot:['Glowmoss','Riverglass','Old Thread']},
  {name:'The Glasswild',biome:'SHATTERED UPLANDS',desc:'Mirrored reeds ring like bells in the wind. Something has been leaving tiny, careful footprints.',glyph:'◇',color:'#83d9dc',art:'linear-gradient(120deg,transparent 58%,#b1e5d155 59% 61%,transparent 62%),radial-gradient(ellipse at 79% 34%,#9bbab0 0 15%,transparent 16%),linear-gradient(155deg,#36536a,#253044 63%,#26253b)',loot:['Prism Shard','Brightsalt','Lost Button']},
  {name:'Cinder Orchard',biome:'EMBERWOOD FRINGE',desc:'Fruit hangs warm as lanterns beneath charcoal branches. The ground remembers a fire—and the hands that planted here again.',glyph:'✹',color:'#ff987e',art:'radial-gradient(ellipse at 78% 27%,#ffb566 0 4%,transparent 5%),radial-gradient(ellipse at 76% 34%,#87584f 0 16%,transparent 17%),linear-gradient(155deg,#563c43,#302b40 60%,#232438)',loot:['Cinderfruit','Ash Petal','Old Thread']},
  {name:'Cloudbreak Shelf',biome:'SKY-SEA COAST',desc:'A shore above the clouds. Pale stones drift like slow thoughts, and a small bell rings where no one stands.',glyph:'☁',color:'#b8a2ff',art:'radial-gradient(ellipse at 79% 30%,#ddd7dc 0 13%,transparent 14%),linear-gradient(170deg,#716990,#4a5272 47%,#29344d 48%,#25263b)',loot:['Sky Salt','Driftwood','Bellflower']},
  {name:'The Blue Below',biome:'SUBTERRANEAN TIDEPOOL',desc:'Under the planet’s skin, a quiet ocean glows blue. Its soft currents seem to know your name already.',glyph:'≈',color:'#83d9dc',art:'radial-gradient(ellipse at 79% 32%,#73cecf 0 4%,transparent 5%),radial-gradient(ellipse at 79% 35%,#358c98 0 20%,transparent 21%),linear-gradient(160deg,#25525d,#202f4a 55%,#202338)',loot:['Deep Pearl','Blue Kelp','Riverglass']},
  {name:'Thornsleep',biome:'ANCIENT WILDS',desc:'A forest of sleeping thorns makes a maze around a single empty chair. A name is carved beneath it.',glyph:'♧',color:'#c8f169',art:'radial-gradient(ellipse at 77% 30%,#9ac66f 0 5%,transparent 6%),radial-gradient(ellipse at 80% 34%,#416751 0 17%,transparent 18%),linear-gradient(145deg,#334b48,#263844 52%,#28273e)',loot:['Heartseed','Nightbloom','Old Thread']}
];
const recipes = [
 {name:'Wayfarer’s Compass',type:'Charm',desc:'A small needle that points toward the next brave thing.',cost:{'Riverglass':1,'Old Thread':1},power:1,icon:'✥'},
 {name:'Mossweave Mantle',type:'Armor',desc:'Soft as lichen, sturdy as a promise kept.',cost:{'Glowmoss':2,'Old Thread':1},power:2,icon:'❋'},
 {name:'Cinderwake Blade',type:'Weapon',desc:'A warm little edge for cutting through tangles.',cost:{'Cinderfruit':1,'Ash Petal':1},power:3,icon:'⚔'},
 {name:'Prismglass Sling',type:'Weapon',desc:'Turns a found pebble into a dazzling distraction.',cost:{'Prism Shard':1,'Brightsalt':1},power:2,icon:'◇'},
 {name:'Cloudstep Boots',type:'Armor',desc:'Light-footed footwear for difficult conversations.',cost:{'Sky Salt':1,'Driftwood':1},power:2,icon:'⌁'},
 {name:'Heartseed Tonic',type:'Potion',desc:'A tiny reserve of courage for a long afternoon.',cost:{'Heartseed':1,'Nightbloom':1},power:3,icon:'♡'},
 {name:'Bluehour Lantern',type:'Charm',desc:'Keeps one gentle light for a friend who is lost.',cost:{'Deep Pearl':1,'Blue Kelp':1},power:2,icon:'☼'},
 {name:'Bellflower Bow',type:'Weapon',desc:'Its bright note makes even shadows look around.',cost:{'Bellflower':1,'Driftwood':1},power:2,icon:'⌒'}
];
const defaultState = {screen:'intro',name:'',className:'Wayfarer',aspectName:'Grove',day:1,level:1,xp:0,hp:10,maxHp:10,grit:0,insight:0,grace:0,items:[],equipped:{Weapon:null,Armor:null,Charm:null},outings:0,story:0,journal:[],seen:[],sound:true};
let state = loadState(), toastTimer;
function loadState(){try{const saved=JSON.parse(localStorage.getItem(SAVE_KEY));return saved?{...structuredClone(defaultState),...saved,equipped:{...defaultState.equipped,...saved.equipped}}:structuredClone(defaultState)}catch{return structuredClone(defaultState)}}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('#save-status').textContent='JOURNAL SAVED'}catch{}}
function h(text=''){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showToast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function klass(){return classes.find(x=>x.name===state.className)||classes[0]}
function aspect(){return aspects.find(x=>x.name===state.aspectName)||aspects[0]}
function addJournal(title,text,icon='✦'){state.journal.unshift({title,text,icon});state.journal=state.journal.slice(0,8)}
function introView(){app.innerHTML=`<section class="intro"><div class="intro-copy"><div class="eyebrow">A COMING-OF-AGE ADVENTURE</div><h1>Somewhere<br>to <em>become.</em></h1><p class="lede">On a planet that grows new places overnight, your class is the way you do things. Your aspect is what you bring into the world. The rest is yours to discover.</p><div class="intro-actions"><button class="button" data-action="begin">Begin your story <span aria-hidden="true">↗</span></button><span class="hero-note">A SMALL, STRANGE WORLD<br>THAT REMEMBERS WHAT YOU DO.</span></div><div class="intro-mini"><div><b>06</b>WAYS TO BE</div><div><b>06</b>WAYS TO CHANGE</div><div><b>∞</b>PLACES TO GROW</div></div></div><div class="hero-art" aria-label="A luminous planet with an alien flower"><div class="planet-scene"><div class="moon"></div><div class="flora"><i class="leaf"></i><i class="leaf l2"></i><i class="leaf l3"></i><i class="leaf l4"></i></div><i class="starlight s1">✦</i><i class="starlight s2">✧</i><i class="starlight s3">✦</i></div><div class="orbit"></div><div class="scene-caption"><span>PLANET VIREL</span> &nbsp;·&nbsp; ORBIT 001</div></div></section>`}
function creationView(){app.innerHTML=`<section class="creation"><div class="creation-head"><div><div class="eyebrow">YOUR FIRST DAY ON VIREL</div><h1>Who are you becoming?</h1><p class="creation-intro">Your class is how you meet the world. Your aspect is what happens when you do. Neither is a box; they're just the first words in your story.</p></div><div class="step-label">FIELD JOURNAL &nbsp; <b>01</b> / 03</div></div><div class="name-row panel"><label for="hero-name">WHAT SHOULD WE CALL YOU?</label><input id="hero-name" maxlength="18" placeholder="A name, or a beginning" value="${h(state.name)}"><span class="pill">✦ &nbsp; LEVEL 01</span></div><div class="creation-grid"><section class="choice-section panel"><div class="eyebrow">CLASS · HOW YOU ACT</div><h2>Choose your way.</h2><p>There's no wrong answer. Each one opens a different path through the same world.</p><div class="choice-list">${classes.map(c=>`<button class="choice-card ${state.className===c.name?'selected':''}" data-class="${c.name}" style="--choice:${c.color}"><span class="choice-icon">${c.icon}</span><span class="choice-copy"><b>${c.name}</b><small>${c.desc}</small></span><span class="check">✦</span></button>`).join('')}</div></section><section class="choice-section panel"><div class="eyebrow">ASPECT · WHAT YOU DO</div><h2>Choose your element.</h2><p>A quality you carry. A force that answers when you reach for it.</p><div class="choice-list">${aspects.map(a=>`<button class="choice-card ${state.aspectName===a.name?'selected':''}" data-aspect="${a.name}" style="--choice:${a.color}"><span class="choice-icon">${a.icon}</span><span class="choice-copy"><b>${a.name}</b><small>${a.tag}</small></span><span class="check">✦</span></button>`).join('')}</div></section></div><div class="creation-bottom"><span class="destiny-preview"><strong>${h(klass().fate)}</strong><br>${h(aspect().bonus)}</span><button class="button" data-action="awaken">Wake up on Virel &nbsp;↗</button></div></section>`}

