const encounters=[
 {title:'A knot in the path',desc:'A bramble has grown around a little wooden gate. From the other side comes the sound of someone humming.',choices:[['Untangle it carefully','A patient hand might be just the thing.'],['Try a little of your aspect','Let your element answer.'],['Call through the gate','There might be a person on the other side.']]},
 {title:'The pocket-sized storm',desc:'A round cloud is caught low between the trees. It is raining upward, and looks embarrassed about it.',choices:[['Offer it a place to rest','Even storms need somewhere safe.'],['Use a clever trick','There may be a way to turn this around.'],['Follow the raindrops','Upward rain must have a source.']]},
 {title:'Something left behind',desc:'Half-buried in the soft earth: a hand-made little thing, clearly important to somebody. A warm light glimmers nearby.',choices:[['Look for its owner','The right person may be close.'],['Repair it here','A mender’s work is never wasted.'],['See what the light wants','It seems to be waiting for you.']]},
 {title:'A shy guardian',desc:'A tangle-beast blocks the trail. It is mostly leaves, two nervous eyes, and a very small thorn crown.',choices:[['Make a friend first','Not every obstacle needs defeating.'],['Meet it with your power','Sometimes a brave hello is loud.'],['Find another way around','There is more than one path.']]}
];
function showEncounter(){const {realm}=state.pending;const enc=encounters[(state.day+state.outings+realm.index)%encounters.length];state.pending.encounter=enc;openModal(`${modalHead(realm.biome,realm.display)}<div class="explore-layout"><div><div class="explore-art" style="--scene-art:${realm.art}"><span class="explore-caption">${realm.biome} · ${String(realm.index+1).padStart(2,'0')}</span></div><p class="explore-text" style="margin:12px 0 0">${realm.desc}</p></div><div><div class="eyebrow">A MOMENT TO CHOOSE</div><h3 style="font-size:19px;margin:9px 0">${enc.title}</h3><p class="explore-text">${enc.desc}</p><div class="explore-options">${enc.choices.map((c,i)=>`<button data-choice="${i}"><strong>${c[0]}</strong><small>${c[1]}</small></button>`).join('')}</div></div></div>`)}
function addXP(amount){state.xp+=amount;let leveled=false;while(state.xp>=needXP()){state.xp-=needXP();state.level++;state.maxHp+=2;state.hp=state.maxHp;state.grit+=klass().stats.grit;state.insight+=klass().stats.insight;state.grace+=klass().stats.grace;leveled=true;state.story=Math.max(state.story,2);addJournal(`Level ${state.level}: a little more you`,`${state.className} meets ${state.aspectName}. You feel the shape of your own becoming.`,'✦')}return leveled}
function addItem(name,count=1){const existing=state.items.find(i=>i.name===name&&!i.made);if(existing)existing.count+=count;else state.items.push({name,count,made:false})}
function resolveChoice(index){const p=state.pending,enc=p.encounter,base=p.realm,choice=enc.choices[index];const stat=index===0?state.grace:index===1?state.grit:state.insight;let chance=.66+Math.min(.18,stat*.025);if((aspect().name==='Gale'&&index===2)||(aspect().name==='Grove'&&index===0)||(aspect().name==='Ember'&&index===1)||(aspect().name==='Hush'&&index===2)||(klass().name==='Mender'&&index===0)||(klass().name==='Seer'&&index===2)||(klass().name==='Ravager'&&index===1))chance+=.15;const success=Math.random()<Math.min(.94,chance);const loot=[];let earned=success?12:6;if(success){let found=base.loot[Math.floor(Math.random()*base.loot.length)];if(aspect().name==='Tide'||(aspect().name==='Hush'&&Math.random()<.45))loot.push(found,base.loot[(base.loot.indexOf(found)+1)%base.loot.length]);else loot.push(found);loot.forEach(n=>addItem(n));if(aspect().name==='Grove'&&state.hp<state.maxHp)state.hp=Math.min(state.maxHp,state.hp+1);if(Math.random()<.32&&state.hp<state.maxHp){state.hp++;}if(enc.title==='A shy guardian')earned+=4}else{const safe=aspect().name==='Stone'||(aspect().name==='Gale'&&index===2);if(!safe){state.hp=Math.max(1,state.hp-1)}if(Math.random()<.45){const found=base.loot[Math.floor(Math.random()*base.loot.length)];loot.push(found);addItem(found)}}
const leveled=addXP(earned);state.day++;state.outings++;state.seen.push(base.name);state.seen=state.seen.slice(-12);state.story=Math.min(3,state.story+1);const narration=success?`You ${choice[0].toLowerCase()} and the moment opens gently. ${state.className} was never about having all the answers; it was about how you stayed with the question.`:`The first try doesn't quite work. You find another way around, a little scuffed but not alone. Even this belongs in your story.`;addJournal(`${base.display}: ${enc.title}`,`${narration} ${loot.length?`You gathered ${loot.join(' and ')}.`:'A new thought follows you home.'}`,'✦');state.pending={phase:'result',success,realm:base,earned,loot,leveled,narration};save();showResult()}
function showResult(){const p=state.pending,icon=p.success?'✦':'⌁',line=p.success?'Something in you and this place met in the middle.':'The world is not a test. You can try another way tomorrow.';openModal(`${modalHead(p.success?'FIELD NOTE · MOMENT KEPT':'FIELD NOTE · STILL LEARNING',p.success?'You found your footing.':'A detour is still a story.')}<div class="result-card"><span class="result-icon">${icon}</span><h3>${p.realm.display}</h3><p>${p.narration}</p><p>${line}</p>${p.loot.length?`<div class="loot-row">${p.loot.map(x=>`<span class="loot-chip">+ ${h(x)}</span>`).join('')}</div>`:''}</div><div style="display:flex;justify-content:space-between;align-items:center"><span class="pill">+${p.earned} GROWTH XP ${p.leveled?' · LEVEL UP ✦':''}</span><button class="button" data-action="finish-outing">Back to the root-house ↗</button></div>`)}
function alchemyModal(){const counts=resourceCounts();openModal(`${modalHead('ROOT-HOUSE WORKBENCH · ALCHEMY','Make something useful.')}<p class="explore-text">Virel's alchemy is mostly paying attention. Combine two found things and see what they might become. Every recipe makes one item.</p><div class="recipe-grid">${recipes.map((r,i)=>{const can=Object.entries(r.cost).every(([n,c])=>(counts[n]||0)>=c);return `<article class="recipe"><h3><span style="color:var(--lime)">${r.icon}</span> &nbsp;${r.name}</h3><p>${r.desc}</p><div class="recipe-footer"><span>${Object.entries(r.cost).map(([n,c])=>`${h(n)} ×${c}`).join(' + ')}</span><button data-craft="${i}" ${can?'':'disabled'}>${can?'COMBINE':'NEED FINDS'}</button></div></article>`}).join('')}</div><div class="recipe-inventory"><span>YOUR INGREDIENTS:</span>${Object.entries(counts).map(([n,c])=>`<span>${h(n)} <b>×${c}</b></span>`).join('')||'<span>Nothing just yet. Try exploring.</span>'}</div>`)}
function craft(index){const recipe=recipes[index];if(!recipe)return;const counts=resourceCounts();if(!Object.entries(recipe.cost).every(([n,c])=>(counts[n]||0)>=c)){showToast('You need a few more ingredients.');return}for(const [name,count] of Object.entries(recipe.cost)){let left=count;for(const item of state.items){if(!item.made&&item.name===name&&left){const used=Math.min(item.count,left);item.count-=used;left-=used}}state.items=state.items.filter(i=>i.made||i.count>0)}state.items.push({name:recipe.name,type:recipe.type,power:recipe.power,made:true,count:1,icon:recipe.icon});addXP(4);addJournal(`Made: ${recipe.name}`,`You mixed found things into ${recipe.name.toLowerCase()}. The workbench smells like possibility.`,'⚗');save();alchemyModal();showToast(`${recipe.name} made!`)}
function equipmentModal(){const made=state.items.filter(i=>i.made);openModal(`${modalHead('WHAT YOU HAVE MADE · ${Object.values(state.equipped).filter(Boolean).length} EQUIPPED','Your kit, so far.')}<div class="equip-list">${made.map((item,index)=>{const isEq=state.equipped[item.type]?.name===item.name;return `<article class="equip-item"><div><b>${item.icon||'✦'} &nbsp;${h(item.name)}</b><small>${h(item.type)} · POWER +${item.power||0}${item.type==='Potion'?' · RESTORES 3 HEALTH':''}</small></div>${item.type==='Potion'?`<button data-use="${index}" ${state.hp>=state.maxHp?'disabled':''}>${state.hp>=state.maxHp?'AT FULL HEALTH':'USE'}</button>`:`<button data-equip="${index}" ${isEq?'disabled':''}>${isEq?'EQUIPPED':'EQUIP'}</button>`}</article>`}).join('')||'<div class="empty">Your pockets are empty. Find a few materials, then try the workbench.</div>'}</div><div class="recipe-inventory"><span>ACTIVE BONUS:</span><b>POWER +${Object.values(state.equipped).filter(Boolean).reduce((n,i)=>n+(i.power||0),0)}</b><span>HEALTH ${state.hp}/${state.maxHp}</span></div>`)}
function equip(index){const item=state.items.filter(i=>i.made)[index];if(!item||!state.equipped[item.type])return;state.equipped[item.type]=item;save();equipmentModal();showToast(`${item.name} equipped.`)}
function usePotion(index){const item=state.items.filter(i=>i.made)[index];if(!item||item.type!=='Potion'||state.hp>=state.maxHp)return;state.hp=Math.min(state.maxHp,state.hp+3);state.items=state.items.filter(i=>i!==item);save();equipmentModal();showToast('You feel steadier. +3 health.')}

