 function gameView(){const need=needXP(),xp=Math.min(100,state.xp/need*100),eq=Object.values(state.equipped).filter(Boolean);$('#footer-day').textContent=String(state.day).padStart(2,'0');app.innerHTML=`<div class="game-layout"><section class="game-main"><div class="welcome-row"><div><div class="eyebrow">DAY ${String(state.day).padStart(2,'0')} · ${state.story<3?'FIRST ROOTS':'A WIDER WORLD'}</div><h1>Good morning, ${h(state.name)}.</h1><p>${h(klass().tag)} &nbsp;·&nbsp; ${h(aspect().tag)}</p></div><div class="day-badge">VIREL LOCAL TIME<strong>${String(state.day).padStart(2,'0')}:17</strong></div></div><article class="scene-card"><div class="scene-content"><div class="scene-location">HOMEBASE · THE ROOT-HOUSE</div><h2>${state.story===0?'The world is listening.':state.story===1?'A place for your own things.':state.story===2?'The horizon keeps unfolding.':'There is always more to mend.'}</h2><p>${state.story===0?'The old root-house creaks awake with you. Somewhere beyond its round windows, a new place has appeared overnight.':state.story===1?'A little workbench fits beneath the window. Your first finds have begun to look like possibilities.':state.story===2?'The planet has started to answer your footsteps. New paths unfurl whenever you are ready to take them.':'Your field journal is filling. Virel has no edge, only another invitation to become.'}</p><div class="scene-footer"><button class="button small" data-action="explore">Choose a new horizon &nbsp;↗</button><span class="scene-coords">N 04° · ROOT DISTRICT</span></div></div><span class="scene-flower" aria-hidden="true">❋</span></article><div class="action-grid"><button class="action-card" data-action="explore"><span class="action-icon">⌁</span><strong>Explore a new realm</strong><small>Find oddities, friends & materials</small></button><button class="action-card" data-action="alchemy"><span class="action-icon">⚗</span><strong>Make something</strong><small>Alchemy & useful junk</small></button><button class="action-card" data-action="journal"><span class="action-icon">▤</span><strong>Read your story</strong><small>See how far you've come</small></button></div><div class="section-title"><h3>Field notes</h3><span>${state.journal.length?`LAST ${state.journal.length} MOMENTS`:'THE FIRST PAGE'}</span></div><div class="journal-list">${state.journal.length?state.journal.slice(0,4).map(n=>`<article class="journal-entry"><span class="journal-icon">${h(n.icon)}</span><div><b>${h(n.title)}</b><small>${h(n.text)}</small></div></article>`).join(''):'<article class="journal-entry"><span class="journal-icon">✦</span><div><b>A blank page, not an empty one.</b><small>Go on. The planet is very good at beginnings.</small></div></article>'}</div></section><aside class="sidebar"><section class="side-panel panel profile-panel"><div class="profile-head"><div class="avatar">${h(klass().icon)}</div><div><h3>${h(state.name)}</h3><small>${h(state.className.toUpperCase())} · ${h(state.aspectName.toUpperCase())}</small></div></div><div class="xp-row"><span>LEVEL ${String(state.level).padStart(2,'0')} · GROWTH</span><span>${state.xp} / ${need} XP</span></div><div class="xp-bar"><i style="width:${xp}%"></i></div><div class="stats-line"><div><b>${state.grit}</b><small>GRIT</small></div><div><b>${state.insight}</b><small>INSIGHT</small></div><div><b>${state.grace}</b><small>GRACE</small></div></div></section><section class="side-panel panel"><h3>On hand</h3>${Object.entries(resourceCounts()).slice(0,5).map(([name,count])=>`<div class="resource-row"><span><i class="resource-gem" style="--res-color:${colorFor(name)}"></i>${h(name)}</span><b>×${count}</b></div>`).join('')||'<div class="resource-row"><span>Nothing yet</span><b>—</b></div>'}<div class="gear-row"><span>Wearing / carrying</span><b>${eq.length} / 3</b></div></section><section class="side-panel panel"><div class="sidebar-actions"><button data-action="alchemy">⚗ &nbsp; ALCHEMY</button><button data-action="equipment">✧ &nbsp; GEAR</button></div></section></aside></div>`}
 function needXP(){return 30+(state.level-1)*15}
 function resourceCounts(){return state.items.reduce((o,item)=>{if(!item.made)o[item.name]=(o[item.name]||0)+item.count;return o},{})}
 function colorFor(name){return ({'Glowmoss':'#b9e983','Riverglass':'#83d9dc','Old Thread':'#c6b8a4','Prism Shard':'#83d9dc','Brightsalt':'#e9d8a4','Cinderfruit':'#ff987e','Ash Petal':'#ff987e','Sky Salt':'#b8a2ff','Driftwood':'#c6b8a4','Heartseed':'#ff987e','Nightbloom':'#b8a2ff','Deep Pearl':'#83d9dc','Blue Kelp':'#83d9dc','Bellflower':'#c8f169'})[name]||'#c8f169'}

