function resolveChoice(index){
 const p=state.pending,enc=p.encounter,base=p.realm,choice=enc.choices[index],trait=element().trait;
 const stat=index===0?state.grace:index===1?state.grit:state.insight;
 let chance=.66+Math.min(.18,stat*.025);
 if(index===archetype().style)chance+=.08;
 if((['drive','craft'].includes(trait)&&index===1)||(['escape','insight'].includes(trait)&&index===2))chance+=.15;
 const power=Object.values(state.equipped).filter(Boolean).reduce((n,i)=>n+(i.power||0),0);
 chance+=Math.min(.1,power*.025);
 const success=Math.random()<Math.min(.94,chance),loot=[];
 let earned=(success?12:6)+(trait==='fate'?3:0);
 if(success){
  const found=base.loot[Math.floor(Math.random()*base.loot.length)];
  loot.push(found);
  if(trait==='resources'||(trait==='hidden'&&Math.random()<.45))loot.push(base.loot[(base.loot.indexOf(found)+1)%base.loot.length]);
  loot.forEach(n=>addItem(n));
  if(trait==='heal'&&state.hp<state.maxHp)state.hp++;
  if(Math.random()<.32&&state.hp<state.maxHp)state.hp++;
  if(enc.title==='A shy guardian')earned+=4;
 }else{
  const safe=trait==='guard'||(trait==='escape'&&index===2)||!!state.equipped.Armor;
  if(!safe)state.hp=Math.max(1,state.hp-1);
  if(Math.random()<.45){const found=base.loot[Math.floor(Math.random()*base.loot.length)];loot.push(found);addItem(found)}
 }
 const leveled=addXP(earned);state.day++;state.outings++;state.seen.push(base.name);state.seen=state.seen.slice(-12);state.story=Math.min(3,state.story+1);
 const narration=success?`You ${choice[0].toLowerCase()} and the moment opens gently. ${state.archetypeName} was never about having all the answers; it was about how you stayed with the question.`:`The first try doesn't quite work. You find another way around, a little scuffed but not alone. Even this belongs in your story.`;
 addJournal(`${base.display}: ${enc.title}`,`${narration} ${loot.length?`You gathered ${loot.join(' and ')}.`:'A new thought follows you home.'}`,'✦');
 state.pending={phase:'result',success,realm:base,earned,loot,leveled,narration};save();showResult()
}

