function applyTheme(realm){const p=realm?.palette;const root=document.documentElement;if(!p){root.removeAttribute('style');return}root.style.setProperty('--lime',p.accent);root.style.setProperty('--bg',p.bg);root.style.setProperty('--panel',p.panel);root.style.setProperty('--panel2',p.panel2);root.style.setProperty('--line',p.line);root.style.setProperty('--theme-glow',p.glow)}
const recipes

function beginRealm(index){const base=realms[index];const variations=['Quiet Verge','New Moon','Far Side','Soft Return','After Rain','Unmapped'];const name=base.name+(state.seen.includes(base.name)?' · '+variations[(state.outings+index)%variations.length]:'');const realm={...base,display:name,index};state.themeRealm=base.name;applyTheme(base);state.pending={realm,phase:'choice'};save();showEncounter()}
const foes=[
 {name:'Rootbound Grazer',icon:'♧',attack:1,health:9,temper:'A shy guardian with a crown of new shoots.'},
 {name:'Shardwing Skitter',icon:'◇',attack:2,health:8,temper:'It darts between reflections, guarding a glimmering nest.'},
 {name:'Cinderling',icon:'✹',attack:2,health:10,temper:'A small ember-beast crackles, more frightened than fierce.'},
 {name:'Cloudmote Wisp',icon:'☁',attack:1,health:9,temper:'A drifting wisp gathers the wind into a protective spiral.'},
 {name:'Tidepool Lurker',icon:'≈',attack:2,health:11,temper:'A bright-eyed creature rises from the quiet blue.'},
 {name:'Thornsleep Stag',icon:'♧',attack:2,health:12,temper:'A sleeping thicket stirs into a watchful, antlered shape.'}
];
function huntModal(){openModal(`${modalHead('FIELD GUIDE · FRIENDLY SPARRING','Who is stirring out there?')}<p class="explore-text">Choose a place to meet one of its wild guardians. Combat is turn-based; your weapon, armor, charm, element, and potions all matter. Victories yield Aether Sap, the living reagent used in alchemy.</p><div class="realm-list">${realms.map((r,i)=>`<button class="realm-card" data-hunt="${i}" data-glyph="${r.glyph}" style="--realm-color:${r.color};--scene-art:${r.art}"><span class="realm-difficulty">${r.biome} · THEMES: ${r.theme.join(' / ')}</span><h3>${r.name}</h3><p>${r.desc}</p></button>`).join('')}</div>`)}
function startCombat(index){const realm=realms[index],foe=foes[index];state.themeRealm=realm.name;applyTheme(realm);state.pending={phase:'combat',realm:{...realm,index},enemy:{...foe},enemyHp:foe.health+(state.level-1)*2,maxEnemyHp:foe.health+(state.level-1)*2,skillReady:true,guard:0,log:`${foe.temper} ${state.name} steps forward.`};save();combatModal()}
function combatModal(){const p=state.pending;if(!p||p.phase!=='combat')return;const enemyPct=Math.max(0,p.enemyHp/p.maxEnemyHp*100),heroPct=Math.max(0,state.hp/state.maxHp*100),potions=state.items.filter(i=>i.made&&i.type==='Potion').reduce((n,i)=>n+i.count,0),gear=state.equipped,weapon=gear.Weapon?.power||0;openModal(`${modalHead(`${p.realm.biome} · ${p.realm.theme.join(' / ')}`,`A wild ${p.enemy.name}`)}<div class="combat-stage" style="--scene-art:${p.realm.art}"><div class="combat-foe">${p.enemy.icon}</div><div class="combat-copy"><div class="eyebrow">${p.enemy.name.toUpperCase()} · ${p.enemy.temper}</div><div class="combat-health"><span>GUARDIAN</span><b>${Math.max(0,p.enemyHp)} / ${p.maxEnemyHp}</b></div><div class="health-bar enemy-bar"><i style="width:${enemyPct}%"></i></div><p>${h(p.log)}</p></div></div><div class="combat-hero"><div><b>${h(state.name)}</b><span>HP ${state.hp}/${state.maxHp} · WEAPON +${weapon} · ARMOR +${gear.Armor?.power||0} · CHARM +${gear.Charm?.power||0}</span></div><div class="health-bar"><i style="width:${heroPct}%"></i></div></div><div class="combat-actions"><button class="button" data-combat="attack">⚔ &nbsp; Strike</button><button class="button secondary" data-combat="skill" ${p.skillReady?'':'disabled'}>✦ &nbsp; Element skill</button><button class="button secondary" data-combat="potion" ${!potions||state.hp>=state.maxHp?'disabled':''}>⚗ &nbsp; Use tonic${potions?` (${potions})`:''}</button><button class="button secondary" data-combat="flee">⌁ &nbsp; Retreat</button></div><p class="combat-hint">GRIT strengthens strikes · INSIGHT sharpens skills · GRACE helps you retreat</p>`)}
function enemyTurn(message,options={}){const p=state.pending;if(!p||p.phase!=='combat')return;if(options.dodge){p.log=`${message} ${p.enemy.name} lashes out, but you slip clear.`;return}const armor=p.guard>0?2:0;p.guard=0;const armorPower=state.equipped.Armor?.power||0;const trait=element().trait;const reduction=Math.floor(armorPower/2)+(trait==='guard'?1:0)+armor;const dodgeChance=Math.min(.35,(state.equipped.Charm?.power||0)*.05+(trait==='escape'?.12:0)+(trait==='misdirection'?.1:0));if(Math.random()<dodgeChance){p.log=`${message} You twist aside from the counterattack.`;return}const damage=Math.max(1,p.enemy.attack+Math.floor((state.level-1)/2)+Math.floor(Math.random()*2)-reduction);state.hp=Math.max(0,state.hp-damage);p.log=`${message} ${p.enemy.name} strikes back for ${damage} damage.`}
function finishCombat(outcome){const p=state.pending,loot=[];let earned=outcome==='victory'?18+(state.level-1)*3:outcome==='defeat'?5:8;if(outcome==='victory'){const sap=2+Math.floor(Math.random()*2);addItem('Aether Sap',sap);loot.push({name:'Aether Sap',count:sap});if(Math.random()<.65){const find=p.realm.loot[Math.floor(Math.random()*p.realm.loot.length)];addItem(find);loot.push({name:find,count:1})}if(element().trait==='fate')earned+=3}else if(outcome==='defeat'){state.hp=1}else if(state.hp<1)state.hp=1;const leveled=addXP(earned);state.day++;state.outings++;state.seen.push(p.realm.name);state.seen=state.seen.slice(-12);state.story=Math.min(3,state.story+1);const text=outcome==='victory'?`You held your ground against ${p.enemy.name}. The guardian left Aether Sap behind, a bright alchemical substance.`:outcome==='defeat'?`${p.enemy.name} drove you back. You made it home safely and know what to prepare next time.`:`You withdrew before the fight could turn worse. The guardian watches you go.`;addJournal(`${outcome==='victory'?'Guardian met':outcome==='defeat'?'A hard-won retreat':'A careful retreat'}: ${p.enemy.name}`,`${text}${loot.length?` You gathered ${loot.map(x=>`${x.name} ×${x.count}`).join(' and ')}.`:''}`,outcome==='victory'?'⚔':'⌁');state.pending={phase:'combat-result',outcome,realm:p.realm,enemy:p.enemy,earned,loot,leveled,text};save();combatResultModal()}
function combatResultModal(){const p=state.pending;const won=p.outcome==='victory';openModal(`${modalHead(won?'FIELD NOTE · GUARDIAN QUIETED':'FIELD NOTE · YOU ARE SAFE',won?`${p.enemy.name} yielded.`:p.outcome==='defeat'?'A step back, not an ending.':'You chose another path.') }<div class="result-card"><span class="result-icon">${won?'⚔':'⌁'}</span><h3>${p.realm.name}</h3><p>${p.text}</p>${p.loot.length?`<div class="loot-row">${p.loot.map(x=>`<span class="loot-chip">+ ${h(x.name)} ×${x.count}</span>`).join('')}</div>`:''}</div><div class="combat-result-foot"><span class="pill">+${p.earned} GROWTH XP ${p.leveled?'· LEVEL UP ✦':''}</span><button class="button" data-action="finish-outing">Back to the root-house ↗</button></div>`)}
function combatAction(action){const p=state.pending;if(!p||p.phase!=='combat')return;let log='';if(action==='attack'){const weapon=state.equipped.Weapon?.power||0;const critChance=Math.min(.5,.08+state.insight*.015+(state.equipped.Charm?.power||0)*.025);let damage=2+weapon+Math.floor(state.grit/3)+Math.floor(Math.random()*2);if(Math.random()<critChance)damage*=2;p.enemyHp=Math.max(0,p.enemyHp-damage);log=`You strike for ${damage}${damage>2+weapon+Math.floor(state.grit/3)?' critical':''} damage.`}else if(action==='skill'){if(!p.skillReady)return;p.skillReady=false;const trait=element().trait;let damage=1+Math.floor(state.insight/2)+(state.equipped.Charm?.power||0);let note='';if(['drive','craft','instinct','truth','fate'].includes(trait)){damage+=trait==='drive'?3:2;note=' Your element turns the opening into force.'}else if(['heal','cultivation','resources'].includes(trait)){damage+=1;state.hp=Math.min(state.maxHp,state.hp+1);note=' The skill steadies you as it lands.'}else if(['guard'].includes(trait)){p.guard=2;note=' A ward will soften the next blow.'}else if(['escape','misdirection','hidden'].includes(trait)){note=' The feint leaves the guardian off-balance.';damage+=2}else if(trait==='truth'){damage+=2}if(trait==='truth')damage+=1;p.enemyHp=Math.max(0,p.enemyHp-damage);log=`${element().name} skill deals ${damage} damage.${note}`}else if(action==='potion'){const item=state.items.find(i=>i.made&&i.type==='Potion');if(!item||state.hp>=state.maxHp)return;state.hp=Math.min(state.maxHp,state.hp+3);item.count--;if(item.count<=0)state.items=state.items.filter(i=>i!==item);log='You drink a tonic and recover 3 health.'}else if(action==='flee'){const chance=Math.min(.95,.55+state.grace*.025+(element().trait==='escape'?.2:0));if(Math.random()<chance){finishCombat('retreat');return}enemyTurn('Your retreat is blocked.');if(state.hp<=0){finishCombat('defeat');return}save();combatModal();return}else return;if(p.enemyHp<=0){finishCombat('victory');return}enemyTurn(log);if(state.hp<=0){finishCombat('defeat');return}save();combatModal()}

