const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const target = targets.find(item => item.type === 'page');
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let nextId = 0;
  const pending = new Map();
  ws.onmessage = event => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) reject(message.error); else resolve(message.result);
    }
  };
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const id = ++nextId;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
  const evaluate = async expression => {
    const result = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (result.exceptionDetails) throw new Error(result.exceptionDetails.text);
    return result.result.value;
  };
  await send('Page.enable');
  await send('Runtime.enable');
  await send('Page.navigate', { url: 'http://127.0.0.1:8765/' });
  await sleep(500);
  const results = {};
  results.intro = await evaluate("document.querySelector('h1')?.innerText");
  await evaluate("document.querySelector('[data-action=begin]').click()");
  await evaluate("document.querySelector('#hero-name').value='Test Star'; document.querySelector('[data-action=awaken]').click()");
  results.starterKit = await evaluate("({items:state.items.filter(x=>x.made).length, slots:Object.values(state.equipped).filter(Boolean).length, equipped:Object.fromEntries(Object.entries(state.equipped).map(([k,v])=>[k,v?.name]))})");
  await evaluate("Math.random=()=>0; document.querySelector('[data-action=hunt]').click(); document.querySelector('[data-hunt=�0]')?.click()".replace("\u00000", "0"));
  results.combatStarted = await evaluate("({phase:state.pending?.phase, heading:document.querySelector('.modal-head h2')?.innerText, theme:document.documentElement.style.getPropertyValue('--bg')})");
  await evaluate("document.querySelector('[data-combat=attack]').click()");
  if (await evaluate("state.pending?.phase==='combat'")) await evaluate("document.querySelector('[data-combat=attack]').click()");
  results.victory = await evaluate("({phase:state.pending?.phase,outcome:state.pending?.outcome,loot:state.pending?.loot, sap:state.items.find(i=>i.name==='Aether Sap')?.count, hp:state.hp})");
  await evaluate("document.querySelector('[data-action=finish-outing]').click(); document.querySelector('[data-action=alchemy]').click()");
  results.sapfireEnabled = await evaluate("({button:document.querySelector('[data-craft="+"8"+"]')?.disabled, ingredients:resourceCounts()})");
  await evaluate("document.querySelector('[data-craft=8]').click()");
  results.crafted = await evaluate("({draught:state.items.find(i=>i.name==='Sapfire Draught')?.count, sap:resourceCounts()['Aether Sap'], glowmoss:resourceCounts().Glowmoss})");
  await evaluate("document.querySelector('[data-action=close]').click(); document.querySelector('[data-action=equipment]').click()");
  results.gearView = await evaluate("({items:document.querySelectorAll('.equip-item').length, equipped:document.querySelectorAll('.equip-item button:disabled').length})");
  await evaluate("document.querySelector('[data-action=close]').click(); document.querySelector('[data-action=hunt]').click(); document.querySelector('[data-hunt=1]').click()");
  results.secondTheme = await evaluate("({theme:document.documentElement.style.getPropertyValue('--bg'), name:document.querySelector('.modal-head .eyebrow')?.innerText})");
  await evaluate("location.reload()");
  await sleep(500);
  results.restore = await evaluate("({screen:state.screen,theme:document.documentElement.style.getPropertyValue('--bg'),savedTheme:state.themeRealm,equipped:Object.values(state.equipped).filter(Boolean).length,items:state.items.filter(i=>i.made).length,sap:resourceCounts()['Aether Sap']})");
  await evaluate("document.querySelector('[data-action=hunt]').click()" );
  await sleep(200);
  results.mobileMetrics = await evaluate("({viewport:innerWidth,document:document.documentElement.scrollWidth,modal:document.querySelector('.modal')?.getBoundingClientRect().width})");
  console.log(JSON.stringify(results, null, 2));
  ws.close();
})().catch(error => { console.error(error); process.exitCode = 1; });

